sys_script_include.script:
var BasesUtilsAjax = Class.create();
BasesUtilsAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


	updateSpaces: function() {
        var grBase = new GlideRecord('x_1590789_bases_base_registration'); 
		var baseNameSysId = this.getParameter('sysparm_base_name');

        if (grBase.get(baseNameSysId)) {
			grBase.available_spaces--; // Reduz o número de vagas disponíveis
            grBase.update(); // Salva as alterações
            return true;
        } else {
            return false;
        }
    },


	updateStatus: function() {
        var grRegistration = new GlideRecord('x_1590789_bases_user_registration'); 
		var registrationSysId = this.getParameter('sysparm_registration_name');

		gs.info(registrationSysId + "  EAID REGISTRATION");

        if (grRegistration.get(registrationSysId)) {
			gs.info("Entrou no registrationSysId");
			grRegistration.setValue('state', "3");
            grRegistration.update(); // Salva as alterações
            return true;
        } else {
			gs.info("Não entrou no registrationSysId");
            return false;
        }
    },

    type: 'BasesUtilsAjax'
});
